            if(IsPossible(nums, limit, mid)) {
                high = mid - 1;
            }
            else {
                low = mid + 1;
            }
        }

        return low;

    }

    private bool IsPossible(int[] nums, int limit, int divisor) {
        int currSum = 0;
        foreach(int i in nums) {
            // currSum += (int)(Math.Ceiling((double)(i / divisor))); // dont use this
            currSum += (i + divisor - 1) / divisor;

            if(currSum > limit) return false;
        }

        return currSum <= limit;
    }
}
